\tblockStmt \*ast\.BlockStmt,
\tcursor \*Cursor,
\tcheck CheckType,
\) \{
\tw\.checkBlock\(blockStmt\)

\tif _, ok := w\.config\.Checks\[check\]; ok \{
\t\tcursor\.SetChecker\(check\)

\t\tblockList := \[\]ast\.Stmt\{\}
\t\tif check != CheckSwitch && check != CheckTypeSwitch \{
\t\t\tblockList = blockStmt\.List
\t\t\}

\t\tw\.checkCuddlingBlock\(node, blockList, cursor, 1\)
\t\}
\}'''

