	node ast.Node,
	blockStmt *ast.BlockStmt,
	cursor *Cursor,
	check CheckType,
) {
	w.checkBlock(blockStmt)

	if _, ok := w.config.Checks[check]; ok {
		cursor.SetChecker(check)

		blockList := []ast.Stmt{}
		switch check {
		case CheckSwitch, CheckTypeSwitch, CheckSelect:
			// For switch, type-switch, and select statements, include case/comm
			// clauses so variables used in them are considered for intersection.
			blockList = blockStmt.List
