	ast.Inspect(file, func(n ast.Node) bool {
		if switchStmt, ok := n.(*ast.SwitchStmt); ok {
			if len(switchStmt.Body.List) > 0 {
				firstCase := switchStmt.Body.List[0]
				idents := identsFromNode(firstCase, true)
				fmt.Printf("Identifiers from first case clause (skipBlock=true):\n")
